"""Exact cached and transparent memoization policy comparisons in SQL.

Canonical syntax facts come from the generic batched CPython producer. Policy
entries are configuration metadata; they are decoded into columns once.
"""
import ast,json,re,unicodedata
from data_layer_six.common import S,q,literals,A,O,K,P,E
from data_layer_eight.relations import clause
from data_layer_eight.model import stages as model

ANCHOR='l2055_lazy_result/cached_pure_lazy_policy.py'
TYPE='l2070_batching.optimizer_run_cache.OptimizerRunCache'


def entries(source, name):
    tree=ast.parse((source/ANCHOR).read_text())
    for node in tree.body:
        if isinstance(node,(ast.Assign,ast.AnnAssign)) and any(isinstance(t,ast.Name) and t.id==name for t in (node.targets if isinstance(node,ast.Assign) else [node.target])):
            return [{k.arg:ast.literal_eval(k.value) for k in item.keywords} for item in node.value.elts]
    raise ValueError(name)


def configured(name,sql,default):
    return {'$option':name,'escape':'sql','template':sql.format('{}'),'default':default}


def normalized_trigger(words):
    """Match the verifier's ASCII trigger words through Unicode compatibility forms.

    These words contain no multi-letter compatibility ligatures. Building the
    character classes once avoids admitting every file with a Unicode comment.
    """
    alphabet=set(''.join(words));variants={char:[char] for char in alphabet}
    for number in range(128,0x110000):
        char=chr(number);normalized=unicodedata.normalize('NFKC',char)
        if normalized in alphabet:variants[normalized].append(char)
    return '(?:'+'|'.join(''.join('['+''.join(re.escape(c) for c in variants[char])+']' if len(variants[char])>1 else re.escape(char) for char in word) for word in words)+')'


def build(stages,query,name,producers):
    # Placeholder SELECTs declare the typed producer schemas to column demand
    # analysis. The authored runtime receives producer contracts, not these SQLs.
    item=clause(name,stages,query,{'strings':E(A(O(K('string'),K('concatenated_string')),P('STRING'),{'regex':r'''(?i)^[ru]*["']'''}),{'value':'capture.DECODED.text'},transform={'DECODED':{'substring':{'source':'$STRING','value':True,'startChar':0}}})})
    plan=item['relational'];plan.pop('partitionBy',None);plan.pop('requireNonemptyInput',None);plan['locations']=[ANCHOR]
    if name=='cached-runtime-contract':
        gate={'filePath':{'regex':r'(?:^|/)(?:l2055_lazy_result/(?:purity|cached_pure_lazy_policy)|l2070_batching/optimizer_run_cache)\.py$'}}
    else:
        gate={'regex':normalized_trigger(['cached_pure_lazy','cache_args'] if name=='cached-policy' else ['memoized_pure_lazy'])}
    plan['inputs']['syntax_gate']['evidence']['query']['ast']['rule']['all'].append(gate)
    if name!='cached-policy':plan['inputs'].pop('raw_strings',None)
    else:plan['inputs']['raw_strings']['evidence']['query']['ast']['rule']['all'].append({'inside':{'kind':'module',**gate,'stopBy':'end'}})
    for stage in plan['stages']:
        if stage['name'] in producers:
            roots,fields=producers[stage['name']]
            stage.clear();stage.update(name=next(k for k,v in producers.items() if v==(roots,fields)),pythonAst={'syntax':'nodes','roots':roots,'fields':fields})
    if name!='cached-runtime-contract':
        # Every consumer reads the same admitted scope. Canonicalize only name
        # tokens, then publish one indexed relation for all syntax consumers.
        plan['syntax']['name']='syntax_nodes'
        for stage in plan['stages']:
            if 'pythonAst' in stage:stage['pythonAst']['syntax']='syntax_nodes'
        columns=plan['syntax']['columns'];projection=[]
        for column in columns:
            if column=='text':expression='coalesce(c.identifier,n.text)'
            elif column.endswith('_source') and column[:-7]+'_id' in columns:
                expression="coalesce((SELECT identifier FROM canonical_names c WHERE c.__path=n.__path AND c.id=n."+column[:-7]+"_id),n."+column+")"
            else:expression='n.'+column
            projection.append(expression+' AS '+column)
        plan['stages'][:0]=[
          {'name':'canonical_names','pythonAst':{'syntax':'syntax_nodes','roots':"SELECT __path,id FROM syntax_nodes WHERE kind IN ('identifier','dotted_name','relative_import') AND rx_matches(text,'[^\\x00-\\x7f]')",'fields':['identifier']}},
          S('nodes','SELECT '+','.join(projection)+' FROM syntax_nodes n LEFT JOIN canonical_names c ON c.__path=n.__path AND c.id=n.id',('__path','id'),('__path','parent'),('__path','kind')),
        ]
    return item


def base(source,kind):
    entry="memoized_policy_violations" if kind=="memoized" else "policy_violations"
    literal=q(json.dumps(entries(source,"_MEMOIZED_POLICY_ENTRIES" if kind=="memoized" else "_POLICY_ENTRIES"),separators=(",",":")))
    columns="SELECT CAST(key AS INTEGER) ordinal,value data,json_extract(value,'$.function') function,json_extract(value,'$.body_hash') body_hash,json_extract(value,'$.signature_hash') signature_hash,json_extract(value,'$.rationale') rationale FROM json_each("
    policies={"$option":"entryPoint","cases":{entry:{"$option":"policyEntries","escape":"sql","template":columns+"{})"}},"default":columns+literal+")"}
    return [*model(),
      S('module_names',"SELECT __path,replace(coalesce(rx_extract(__path,'(?:^|/)((?:l[0-9]{4}_[^/]+|impl|_internal|data_layer)/.*)\\.py$',1),substr(__path,1,length(__path)-3)),'/','.') module FROM nodes WHERE kind='module'",('__path',)),
      S('policy_records',policies,('function',)),
      S('policy_entries',"SELECT p.* FROM policy_records p WHERE p.ordinal=(SELECT max(x.ordinal) FROM policy_records x WHERE x.function=p.function)",('function',)),
      S('eligible_declarations',"SELECT d.*,m.module||'.'||coalesce((SELECT group_concat(part,'.') FROM (SELECT a.name||CASE WHEN a.kind='function_definition' THEN '.<locals>' ELSE '' END part FROM declarations a WHERE a.__path=d.__path AND a.region_start<d.region_start AND a.__end>=d.__end ORDER BY a.region_start))||'.','')||d.name function FROM declaration_contexts d JOIN module_names m ON m.__path=d.__path WHERE d.kind='function_definition' AND NOT EXISTS(SELECT 1 FROM nodes wrapper JOIN nodes parent ON parent.__path=wrapper.__path AND parent.id=wrapper.parent WHERE wrapper.__path=d.__path AND (wrapper.id=d.id OR wrapper.id=d.parent AND wrapper.kind='decorated_definition') AND parent.kind NOT IN ('module','block','decorated_definition'))",('__path','id')),
    ]


def candidate(source,policy):
    p=policy('cached_pure_lazy_allowlist',['impl/**/*.py','data_layer/**/*.py','_internal/**/*.py','l[0-9][0-9][0-9][0-9]_*/**/*.py'])
    default=json.dumps(entries(source,'_POLICY_ENTRIES'),separators=(',',':'))
    p['clauses'].append({'id':'entry','define':{'options':{'oracleAnalyzer':{'type':'boolean','default':False},'entryPoint':{'type':'string','default':'all'},'policyEntries':{'type':'string','default':default}}}})
    p['clauses'].extend([cached(source),memoized(source),runtime_contract(source)]);return p


def declaration_facts(kind):
    return [S('selected_functions',"SELECT f.*,c.id decorator FROM eligible_declarations f JOIN decorator_names d ON d.__path=f.__path AND d.fn=f.id JOIN calls c ON c.__path=d.__path AND c.callee_id=d.node AND c.parent=d.decorator WHERE "+("d.name='memoized_pure_lazy' AND c.callee_kind='identifier'" if kind=='memoized' else "(d.name='cached_pure_lazy' OR c.callee_kind='identifier' AND EXISTS(SELECT 1 FROM cached_aliases a WHERE a.__path=c.__path AND a.name=c.callee))")+" GROUP BY f.__path,f.id",('__path','id')),
      S('fingerprints',"SELECT __path,id,'' body_sha256,'' signature_sha256 FROM selected_functions",('__path','id')),
      S('actual_functions',"SELECT f.__path,f.id,f.function,h.body_sha256,h.signature_sha256 FROM selected_functions f JOIN fingerprints h ON h.__path=f.__path AND h.id=f.id",('function',)),
    ]


def output(stage,entry):
    query="SELECT "+q(ANCHOR)+" path,0 start_byte,0 end_byte,issue,issue identity FROM "+stage
    return {'$option':'entryPoint','cases':{entry:query,'all':query},'default':query+' WHERE 0'}


def memoized(source):
    stages=base(source,"memoized")+declaration_facts('memoized')+[
      S('memoized_bounds',"SELECT f.__path,f.id,k.kind,k.text,k.value,CASE WHEN k.kind='integer' THEN CAST(replace(k.text,'_','') AS INTEGER) END max_entries FROM selected_functions f LEFT JOIN keywords k ON k.__path=f.__path AND k.call=f.decorator AND k.name='max_entries'",('__path','id')),
      S('memoized_errors',"SELECT f.function,'memoized_pure_lazy requires the canonical pure_lazy marker' error FROM selected_functions f WHERE NOT EXISTS(SELECT 1 FROM decorator_names d JOIN nodes n ON n.__path=d.__path AND n.id=d.node JOIN nodes par ON par.__path=n.__path AND par.id=n.parent WHERE d.__path=f.__path AND d.fn=f.id AND d.name='pure_lazy' AND n.kind='identifier' AND par.kind='decorator') UNION ALL SELECT f.function,'memoized_pure_lazy requires one literal max_entries keyword' FROM selected_functions f WHERE (SELECT count(*) FROM keywords k WHERE k.__path=f.__path AND k.call=f.decorator)!=1 OR NOT EXISTS(SELECT 1 FROM keywords k WHERE k.__path=f.__path AND k.call=f.decorator AND k.name='max_entries') OR EXISTS(SELECT 1 FROM arguments a WHERE a.__path=f.__path AND a.call=f.decorator) UNION ALL SELECT f.function,'memoized_pure_lazy max_entries must be a literal integer' FROM selected_functions f JOIN memoized_bounds b ON b.__path=f.__path AND b.id=f.id WHERE b.max_entries IS NULL AND b.value IS NOT NULL UNION ALL SELECT f.function,'memoized_pure_lazy max_entries must be positive' FROM selected_functions f JOIN memoized_bounds b ON b.__path=f.__path AND b.id=f.id WHERE b.max_entries<1 UNION ALL SELECT function,'memoized pure-lazy functions must be synchronous' FROM selected_functions WHERE rx_matches(text,'^async\\s') UNION ALL SELECT f.function,'memoized pure-lazy functions cannot use variadic arguments' FROM selected_functions f WHERE EXISTS(SELECT 1 FROM nodes n WHERE n.__path=f.__path AND n.__start>=f.parameters_start AND n.__end<=f.parameters_end AND n.kind IN ('list_splat_pattern','dictionary_splat_pattern')) UNION ALL SELECT f.function,'memoized pure-lazy functions cannot be generators' FROM selected_functions f WHERE EXISTS(SELECT 1 FROM nodes n WHERE n.__path=f.__path AND n.__start>=f.body_start AND n.__end<=f.body_end AND n.kind='yield')"),
      S('memoized_aliases',"SELECT m.module||'.<memoized_decorator_alias_'||(n.line+1)||'>' function,'memoized_pure_lazy decorator aliases are forbidden' error FROM nodes n JOIN module_names m ON m.__path=n.__path JOIN nodes a ON a.__path=n.__path AND a.parent=n.id WHERE n.kind='import_from_statement' AND n.module_name_source='l2055_lazy_result.purity' AND a.kind='aliased_import' AND a.name_source='memoized_pure_lazy' UNION ALL SELECT m.module||'.<private_memoized_storage_access_'||(n.line+1)||'_'||(SELECT column FROM coordinates h WHERE h.__path=n.__path AND h.id=n.id)||'>','direct access to private memoization storage is forbidden' FROM nodes n JOIN module_names m ON m.__path=n.__path LEFT JOIN nodes par ON par.__path=n.__path AND par.id=n.parent WHERE n.kind='identifier' AND n.text IN ('_MEMOIZED_PURE_LAZY_STATE_CREATION_LOCK','_MemoizedPureLazyState','_memoized_purity_decorator') AND par.kind NOT IN ('dotted_name','aliased_import','import_from_statement') AND n.__path NOT LIKE '%l2055_lazy_result/purity.py'"),
      S('all_memoized',"SELECT function FROM actual_functions UNION ALL SELECT function FROM memoized_aliases",('function',)),
      S('memoized_comparisons',"SELECT a.function,'memoization bound changed' error FROM actual_functions a JOIN policy_entries e ON e.function=a.function JOIN memoized_bounds b ON b.__path=a.__path AND b.id=a.id WHERE b.max_entries IS NOT json_extract(e.data,'$.max_entries') UNION ALL "+' UNION ALL '.join("SELECT a.function,"+q(message)+" error FROM actual_functions a JOIN policy_entries e ON e.function=a.function WHERE json_extract(e.data,"+q('$.'+field)+") IS NOT "+q(value) for field,value,message in [('cache_lifetime','process','cache lifetime is not approved'),('key_policy','bound_explicit_immutable_v1','key policy is not approved'),('return_policy','immutable_no_alias_v1','return policy is not approved'),('exception_policy','successful_results_only_v1','exception policy is not approved')])+" UNION ALL SELECT a.function,'review rationale is required' FROM actual_functions a JOIN policy_entries e ON e.function=a.function WHERE trim(e.rationale)='' UNION ALL SELECT a.function,'function body hash changed' FROM actual_functions a JOIN policy_entries e ON e.function=a.function WHERE a.body_sha256!=e.body_hash UNION ALL SELECT a.function,'function signature hash changed' FROM actual_functions a JOIN policy_entries e ON e.function=a.function WHERE a.signature_sha256!=e.signature_hash"),
      S('diagnostics',"SELECT 'unsigned memoized pure-lazy function: '||a.function issue FROM all_memoized a WHERE NOT EXISTS(SELECT 1 FROM policy_entries p WHERE p.function=a.function) UNION ALL SELECT 'stale memoized pure-lazy policy entry: '||p.function FROM policy_entries p WHERE NOT EXISTS(SELECT 1 FROM all_memoized a WHERE a.function=p.function) UNION ALL SELECT function||': '||error FROM memoized_errors UNION ALL SELECT function||': '||error FROM memoized_aliases UNION ALL SELECT function||': '||error FROM memoized_comparisons UNION ALL SELECT 'duplicate memoized decorator entry: '||function FROM all_memoized GROUP BY function HAVING count(*)>1 UNION ALL SELECT 'duplicate memoized policy entry: '||function FROM policy_records GROUP BY function HAVING count(*)>1"),
    ]
    coordinates=[S('coordinate_roots',"SELECT __path,id FROM nodes WHERE kind='identifier' AND text IN ('_MEMOIZED_PURE_LAZY_STATE_CREATION_LOCK','_MemoizedPureLazyState','_memoized_purity_decorator') AND __path NOT LIKE '%l2055_lazy_result/purity.py'",('__path','id')),S('coordinates',"SELECT __path,id,'' column FROM coordinate_roots",('__path','id'))]
    index=next(i for i,stage in enumerate(stages) if stage['name']=='memoized_aliases')
    stages[index:index]=coordinates
    return build(stages,output('diagnostics','memoized_policy_violations'),'memoized-policy',{'coordinates':('SELECT __path,id FROM coordinate_roots',['column']),'fingerprints':('SELECT __path,id FROM selected_functions',['body_sha256','signature_sha256'])})


def cached(source):
    stages=base(source,"cached")+[
      S('cached_aliases',"WITH RECURSIVE aliases(__path,name) AS (SELECT __path,'cached_pure_lazy' FROM nodes WHERE kind='module' UNION SELECT n.__path,coalesce(a.alias_source,a.name_source,a.text) FROM nodes n JOIN nodes a ON a.__path=n.__path AND a.parent=n.id WHERE n.kind='import_from_statement' AND n.module_name_source='l2055_lazy_result.purity' AND coalesce(a.name_source,a.text)='cached_pure_lazy' UNION SELECT a.__path,a.target_text FROM assignments a JOIN attributes attr ON attr.__path=a.__path AND attr.id=a.value WHERE a.target_kind='identifier' AND attr.attr='cached_pure_lazy' UNION SELECT a.__path,a.target_text FROM assignments a JOIN aliases old ON old.__path=a.__path AND old.name=a.expr_text WHERE a.target_kind='identifier' AND a.expr_kind='identifier') SELECT * FROM aliases",('__path','name')),
    ]+declaration_facts('cached')+[
      S('cache_arguments',"SELECT f.__path,f.id fn,CAST(x.ordinal AS INTEGER) ordinal,s.value name FROM selected_functions f JOIN keywords k ON k.__path=f.__path AND k.call=f.decorator AND k.name='cache_args' JOIN nodes container ON container.__path=k.__path AND container.id=k.value AND container.kind IN ('tuple','list') JOIN nodes x ON x.__path=container.__path AND x.parent=container.id JOIN strings s ON s.__path=x.__path AND s.__start=x.__start WHERE NOT EXISTS(SELECT 1 FROM arguments a WHERE a.__path=f.__path AND a.call=f.decorator) AND (SELECT count(*) FROM keywords kw WHERE kw.__path=f.__path AND kw.call=f.decorator)=1 AND NOT EXISTS(SELECT 1 FROM nodes n WHERE n.__path=container.__path AND n.parent=container.id AND n.kind NOT IN ('string','concatenated_string','comment'))",('__path','fn','name')),
      S('cache_names',"SELECT f.__path,f.id fn,n.* FROM selected_functions f JOIN nodes n ON n.__path=f.__path AND n.__start>=f.body_start AND n.__end<=f.body_end JOIN cache_arguments a ON a.__path=f.__path AND a.fn=f.id AND a.name=n.text LEFT JOIN nodes par ON par.__path=n.__path AND par.id=n.parent WHERE n.kind='identifier' AND NOT (par.kind='attribute' AND n.id=par.attribute_kind||':'||par.attribute_start||':'||par.attribute_end)",('__path','fn','id')),
      S('attribute_paths',"""WITH RECURSIVE path(__path,id,name,member) AS (
        SELECT a.__path,a.id,n.text,a.attr FROM attributes a JOIN nodes n ON n.__path=a.__path AND n.id=a.object WHERE n.kind='identifier'
        UNION ALL SELECT a.__path,a.id,p.name,p.member||'.'||a.attr FROM path p JOIN attributes a ON a.__path=p.__path AND a.object=p.id)
        SELECT * FROM path""",('__path','id')),
      S('cache_attributes',"SELECT f.__path,f.id fn,a.*,root.member,par.kind parent_kind,par.id parent_id,CASE WHEN EXISTS(SELECT 1 FROM calls c WHERE c.__path=a.__path AND c.callee_id=a.id) THEN 'call' WHEN EXISTS(SELECT 1 FROM calls c JOIN arguments arg ON arg.__path=c.__path AND arg.call=c.id WHERE c.__path=a.__path AND arg.id=a.id) THEN 'resolver' ELSE 'read' END mode FROM selected_functions f JOIN attributes a ON a.__path=f.__path AND a.__start>=f.body_start AND a.__end<=f.body_end JOIN attribute_paths root ON root.__path=a.__path AND root.id=a.id JOIN cache_arguments arg ON arg.__path=f.__path AND arg.fn=f.id AND arg.name=root.name JOIN nodes par ON par.__path=a.__path AND par.id=a.parent WHERE NOT (par.kind='attribute' AND par.object_kind||':'||par.object_start||':'||par.object_end=a.id)",('__path','fn','id')),
      S('mutations',"SELECT a.__path,a.fn,a.id FROM cache_attributes a WHERE EXISTS(SELECT 1 FROM assignments x WHERE x.__path=a.__path AND x.target=a.id) OR a.parent_kind='delete_statement'",('__path','id')),
      S('member_aliases',"SELECT a.__path,a.fn,a.id FROM cache_attributes a WHERE EXISTS(SELECT 1 FROM assignments x WHERE x.__path=a.__path AND x.value=a.id)",('__path','id')),
      S('cache_members',"SELECT DISTINCT a.__path,a.fn,rx_replace(a.member,'\\s+','') member,a.mode FROM cache_attributes a WHERE NOT EXISTS(SELECT 1 FROM mutations x WHERE x.__path=a.__path AND x.id=a.id) AND NOT EXISTS(SELECT 1 FROM member_aliases x WHERE x.__path=a.__path AND x.id=a.id) AND a.member NOT IN ('__class__','__delattr__','__dict__','__getattribute__','__setattr__')",('__path','fn')),
      S('mutable_globals',"SELECT a.__path,b.name FROM assignments a JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id JOIN nodes stmt ON stmt.__path=a.__path AND stmt.id=a.parent JOIN nodes parent ON parent.__path=stmt.__path AND parent.id=stmt.parent WHERE parent.kind='module' AND a.expr_kind NOT IN ('string','concatenated_string','integer','float','true','false','none') AND NOT (a.expr_kind='tuple' AND NOT EXISTS(SELECT 1 FROM nodes n WHERE n.__path=a.__path AND n.__start>a.right_start AND n.__end<a.right_end AND n.kind IN ('identifier','call','list','dictionary','set'))) AND NOT (a.expr_kind='call' AND EXISTS(SELECT 1 FROM calls c WHERE c.__path=a.__path AND c.id=a.value AND c.callee_kind='identifier' AND c.callee='frozenset') AND NOT EXISTS(SELECT 1 FROM keywords k WHERE k.__path=a.__path AND k.call=a.value))",('__path','name')),
      S('extra_cached_errors',"SELECT arg.__path,arg.fn,'cache argument '||quote(arg.name)||' cannot have a default' error FROM cache_arguments arg JOIN parameters p ON p.__path=arg.__path AND p.fn=arg.fn AND p.name=arg.name WHERE p.kind IN ('default_parameter','typed_default_parameter') UNION ALL SELECT arg.__path,arg.fn,'cache argument '||quote(arg.name)||' must be keyword-only' FROM cache_arguments arg JOIN parameters p ON p.__path=arg.__path AND p.fn=arg.fn AND p.name=arg.name JOIN nodes param ON param.__path=p.__path AND param.id=p.id JOIN selected_functions f ON f.__path=p.__path AND f.id=p.fn WHERE arg.name!='self' AND NOT EXISTS(SELECT 1 FROM nodes star WHERE star.__path=f.__path AND star.parent=f.parameters_kind||':'||f.parameters_start||':'||f.parameters_end AND star.__start<param.__start AND star.kind IN ('keyword_separator','list_splat_pattern')) UNION ALL SELECT f.__path,f.id,'a cache argument cannot be captured by a closure' FROM selected_functions f JOIN nodes closure ON closure.__path=f.__path AND closure.__start>=f.body_start AND closure.__end<=f.body_end AND closure.kind IN ('function_definition','lambda','generator_expression') WHERE EXISTS(SELECT 1 FROM cache_names n WHERE n.__path=f.__path AND n.fn=f.id AND n.__start>=closure.__start AND n.__end<=closure.__end) UNION ALL SELECT f.__path,f.id,c.callee||'() on a cache argument is forbidden' FROM selected_functions f JOIN calls c ON c.__path=f.__path AND c.__start>=f.body_start AND c.__end<=f.body_end AND c.callee_kind='identifier' AND c.callee IN ('delattr','getattr','hasattr','setattr','vars') WHERE EXISTS(SELECT 1 FROM arguments a JOIN cache_names n ON n.__path=a.__path AND n.__start>=a.__start AND n.__end<=a.__end AND n.fn=f.id WHERE a.__path=c.__path AND a.call=c.id) UNION ALL SELECT f.__path,f.id,'cached pure-lazy functions cannot read mutable global state '||quote(g.name) FROM selected_functions f JOIN mutable_globals g ON g.__path=f.__path JOIN nodes n ON n.__path=f.__path AND n.__start>=f.body_start AND n.__end<=f.body_end AND n.kind='identifier' AND n.text=g.name JOIN nodes par ON par.__path=n.__path AND par.id=n.parent WHERE par.kind NOT IN ('global_statement','nonlocal_statement') AND NOT(par.kind='attribute' AND par.attribute_kind||':'||par.attribute_start||':'||par.attribute_end=n.id) AND NOT EXISTS(SELECT 1 FROM assignments a WHERE a.__path=n.__path AND a.target=n.id)"),
      S('cached_errors',"SELECT f.__path,f.id fn,'cached pure-lazy functions must be synchronous' error FROM selected_functions f WHERE rx_matches(f.text,'^async\\s') UNION ALL SELECT f.__path,f.id,'cached pure-lazy functions cannot use variadic arguments' FROM selected_functions f WHERE EXISTS(SELECT 1 FROM nodes n WHERE n.__path=f.__path AND n.__start>=f.parameters_start AND n.__end<=f.parameters_end AND n.kind IN ('list_splat_pattern','dictionary_splat_pattern')) UNION ALL SELECT f.__path,f.id,'cached pure-lazy functions cannot be generators' FROM selected_functions f WHERE EXISTS(SELECT 1 FROM nodes n WHERE n.__path=f.__path AND n.__start>=f.body_start AND n.__end<=f.body_end AND n.kind='yield') UNION ALL SELECT n.__path,n.fn,'a cache argument can only be used through signed member access' FROM cache_names n JOIN nodes par ON par.__path=n.__path AND par.id=n.parent WHERE NOT(par.kind='attribute' AND par.object_kind||':'||par.object_start||':'||par.object_end=n.id) UNION ALL SELECT f.__path,f.id,'a cache argument cannot escape through return' FROM selected_functions f JOIN returns r ON r.__path=f.__path AND r.__start>=f.body_start AND r.__end<=f.body_end WHERE EXISTS(SELECT 1 FROM cache_names n WHERE n.__path=f.__path AND n.fn=f.id AND n.__start>=r.__start AND n.__end<=r.__end) UNION ALL SELECT f.__path,f.id,'cached pure-lazy functions cannot write mutable global state' FROM selected_functions f WHERE EXISTS(SELECT 1 FROM nodes n WHERE n.__path=f.__path AND n.__start>=f.body_start AND n.__end<=f.body_end AND n.kind IN ('global_statement','nonlocal_statement')) UNION ALL SELECT a.__path,a.fn,'direct cache attribute mutation '||quote(a.member)||' is forbidden' FROM cache_attributes a JOIN mutations x ON x.__path=a.__path AND x.id=a.id UNION ALL SELECT a.__path,a.fn,'cache member alias '||quote(a.member)||' is forbidden' FROM cache_attributes a JOIN member_aliases x ON x.__path=a.__path AND x.id=a.id UNION ALL SELECT a.__path,a.fn,'cache subscript '||CASE WHEN EXISTS(SELECT 1 FROM assignments x WHERE x.__path=n.__path AND x.target=n.id) OR par.kind='delete_statement' THEN 'mutation' ELSE 'access' END||' through '||quote(a.member)||' is forbidden' FROM cache_attributes a JOIN nodes n ON n.__path=a.__path AND n.id=a.parent_id AND n.kind='subscript' JOIN nodes par ON par.__path=n.__path AND par.id=n.parent UNION ALL SELECT a.__path,a.fn,'dynamic cache access '||quote(a.member)||' is forbidden' FROM cache_attributes a WHERE a.member IN ('__class__','__delattr__','__dict__','__getattribute__','__setattr__') UNION ALL SELECT arg.__path,arg.fn,'cache argument '||quote(arg.name)||' requires an exact annotation' FROM cache_arguments arg WHERE NOT EXISTS(SELECT 1 FROM parameters p WHERE p.__path=arg.__path AND p.fn=arg.fn AND p.name=arg.name AND p.annotation IS NOT NULL)"),
      S('policy_args',"SELECT p.function,x.key ordinal,x.value name FROM policy_entries p,json_each(p.data,'$.cache_args') x",('function','name')),
      S('policy_types',"SELECT p.function,x.key ordinal,json_extract(x.value,'$[0]') name,json_extract(x.value,'$[1]') type FROM policy_entries p,json_each(p.data,'$.cache_types') x",('function','name')),
      S('policy_members',"SELECT p.function,x.key ordinal,json_extract(x.value,'$[0]') member,json_extract(x.value,'$[1]') mode FROM policy_entries p,json_each(p.data,'$.allowed_cache_members') x",('function',)),
      S('member_reprs',"SELECT f.function,coalesce((SELECT '('||group_concat(pair,', ')||CASE WHEN count(*)=1 THEN ',' ELSE '' END||')' FROM (SELECT '('||quote(member)||', '||quote(mode)||')' pair FROM cache_members m WHERE m.__path=f.__path AND m.fn=f.id ORDER BY member,mode)),'()') actual,coalesce((SELECT '('||group_concat(pair,', ')||CASE WHEN count(*)=1 THEN ',' ELSE '' END||')' FROM (SELECT '('||quote(member)||', '||quote(mode)||')' pair FROM policy_members m WHERE m.function=f.function ORDER BY ordinal)),'()') policy FROM actual_functions f",('function',)),
      S('annotation_values',"SELECT p.__path,p.annotation id,'' unparse,'' repr_unparse FROM parameters p JOIN cache_arguments a ON a.__path=p.__path AND a.fn=p.fn AND a.name=p.name WHERE p.annotation IS NOT NULL",('__path','id')),
      S('cached_comparisons',"SELECT f.function,e.error FROM actual_functions f JOIN policy_entries p ON p.function=f.function JOIN (SELECT * FROM cached_errors UNION SELECT * FROM extra_cached_errors) e ON e.__path=f.__path AND e.fn=f.id UNION SELECT f.function,'decorator cache arguments changed' FROM actual_functions f JOIN policy_entries p ON p.function=f.function WHERE EXISTS(SELECT ordinal,name FROM cache_arguments a WHERE a.__path=f.__path AND a.fn=f.id EXCEPT SELECT ordinal,name FROM policy_args a WHERE a.function=f.function) OR EXISTS(SELECT ordinal,name FROM policy_args a WHERE a.function=f.function EXCEPT SELECT ordinal,name FROM cache_arguments a WHERE a.__path=f.__path AND a.fn=f.id) UNION SELECT f.function,'cache type metadata must name each cache argument exactly once' FROM actual_functions f JOIN policy_entries p ON p.function=f.function WHERE EXISTS(SELECT name FROM policy_types t WHERE t.function=f.function GROUP BY name HAVING count(*)>1) OR EXISTS(SELECT name FROM policy_args a WHERE a.function=f.function EXCEPT SELECT name FROM policy_types t WHERE t.function=f.function) OR EXISTS(SELECT name FROM policy_types t WHERE t.function=f.function EXCEPT SELECT name FROM policy_args a WHERE a.function=f.function) UNION SELECT f.function,'cache type '||quote(t.type)||' is not approved' FROM actual_functions f JOIN policy_types t ON t.function=f.function WHERE t.type!="+q(TYPE)+" UNION SELECT f.function,'cache argument '||quote(t.name)||' annotation '||coalesce(annotation.repr_unparse,'None')||' does not match cache type '||quote(t.type) FROM actual_functions f JOIN policy_types t ON t.function=f.function LEFT JOIN parameters a ON a.__path=f.__path AND a.fn=f.id AND a.name=t.name LEFT JOIN annotation_values annotation ON annotation.__path=a.__path AND annotation.id=a.annotation WHERE annotation.unparse IS NOT rx_replace(t.type,'^.*\\.','') UNION SELECT f.function,'owner scope '||quote(json_extract(p.data,'$.owner_scope'))||' is not approved' FROM actual_functions f JOIN policy_entries p ON p.function=f.function WHERE json_extract(p.data,'$.owner_scope')!='optimizer_run' UNION SELECT f.function,'review rationale is required' FROM actual_functions f JOIN policy_entries p ON p.function=f.function WHERE trim(p.rationale)='' UNION SELECT f.function,'cache member access modes are invalid: ['||(SELECT group_concat(quote(mode),', ') FROM (SELECT DISTINCT mode FROM policy_members m WHERE m.function=f.function AND mode NOT IN ('call','read','resolver') ORDER BY mode))||']' FROM actual_functions f JOIN policy_entries p ON p.function=f.function WHERE EXISTS(SELECT 1 FROM policy_members m WHERE m.function=f.function AND mode NOT IN ('call','read','resolver')) UNION SELECT f.function,'function body hash changed' FROM actual_functions f JOIN policy_entries p ON p.function=f.function WHERE f.body_sha256!=p.body_hash UNION SELECT f.function,'function signature hash changed' FROM actual_functions f JOIN policy_entries p ON p.function=f.function WHERE f.signature_sha256!=p.signature_hash UNION SELECT f.function,'cache member access changed: actual='||r.actual||' policy='||r.policy FROM actual_functions f JOIN policy_entries p ON p.function=f.function JOIN member_reprs r ON r.function=f.function WHERE r.actual!=r.policy"),
      S('diagnostics',"SELECT 'unsigned cached pure-lazy function: '||f.function issue FROM actual_functions f WHERE NOT EXISTS(SELECT 1 FROM policy_entries p WHERE p.function=f.function) UNION ALL SELECT 'stale cached pure-lazy policy entry: '||p.function FROM policy_entries p WHERE NOT EXISTS(SELECT 1 FROM actual_functions f WHERE f.function=p.function) UNION ALL SELECT function||': '||error FROM cached_comparisons UNION ALL SELECT 'duplicate decorator entry: '||function FROM actual_functions GROUP BY function HAVING count(*)>1 UNION ALL SELECT 'duplicate policy entry: '||function FROM policy_records GROUP BY function HAVING count(*)>1"),
    ]
    # Unsupported calls and escaped decorator values are declarations in the
    # upstream closed-domain policy. Keep their source identities and errors.
    pseudo=[
      S('coordinate_roots',"SELECT c.__path,c.id FROM calls c WHERE c.callee='cached_pure_lazy' OR c.callee_kind='identifier' AND EXISTS(SELECT 1 FROM cached_aliases a WHERE a.__path=c.__path AND a.name=c.callee) OR EXISTS(SELECT 1 FROM keywords k WHERE k.__path=c.__path AND k.call=c.id AND k.name='cache_args') UNION SELECT n.__path,n.id FROM nodes n WHERE n.kind='identifier' AND EXISTS(SELECT 1 FROM cached_aliases a WHERE a.__path=n.__path AND a.name=n.text) OR n.kind='attribute' AND n.attribute_source='cached_pure_lazy'",('__path','id')),
      S('coordinates',"SELECT __path,id,'' column FROM coordinate_roots",('__path','id')),
      S('pseudo_cached',"SELECT c.__path,c.id,m.module||'.<unsupported_cached_pure_lazy_call_'||(c.line+1)||'_'||(SELECT column FROM coordinates h WHERE h.__path=c.__path AND h.id=c.id)||'>' function,CASE WHEN c.callee='cached_pure_lazy' OR c.callee_kind='identifier' AND EXISTS(SELECT 1 FROM cached_aliases a WHERE a.__path=c.__path AND a.name=c.callee) THEN 'cached_pure_lazy must use decorator syntax' ELSE 'unresolved cache decorator alias is forbidden' END error FROM calls c JOIN module_names m ON m.__path=c.__path WHERE c.callee!='CachedPureLazyPolicyEntry' AND (c.callee='cached_pure_lazy' OR c.callee_kind='identifier' AND EXISTS(SELECT 1 FROM cached_aliases a WHERE a.__path=c.__path AND a.name=c.callee) OR EXISTS(SELECT 1 FROM keywords k WHERE k.__path=c.__path AND k.call=c.id AND k.name='cache_args')) AND NOT EXISTS(SELECT 1 FROM decorator_names d WHERE d.__path=c.__path AND d.node=c.callee_id AND d.decorator=c.parent AND (d.name='cached_pure_lazy' OR c.callee_kind='identifier' AND EXISTS(SELECT 1 FROM cached_aliases a WHERE a.__path=c.__path AND a.name=c.callee))) UNION ALL SELECT n.__path,n.id,m.module||'.<escaped_cached_pure_lazy_reference_'||(n.line+1)||'_'||(SELECT column FROM coordinates h WHERE h.__path=n.__path AND h.id=n.id)||'>','cached_pure_lazy cannot escape as a first-class value' FROM nodes n JOIN module_names m ON m.__path=n.__path JOIN nodes par ON par.__path=n.__path AND par.id=n.parent WHERE (n.kind='identifier' AND EXISTS(SELECT 1 FROM cached_aliases a WHERE a.__path=n.__path AND a.name=n.text) OR n.kind='attribute' AND n.attribute_source='cached_pure_lazy') AND par.kind NOT IN ('dotted_name','aliased_import','import_from_statement','import_statement') AND NOT(n.kind='identifier' AND par.kind IN ('function_definition','class_definition','attribute','keyword_argument','typed_parameter','typed_default_parameter','default_parameter','parameters') AND (par.kind='parameters' OR n.id=par.name_kind||':'||par.name_start||':'||par.name_end OR par.kind='attribute' AND n.id=par.attribute_kind||':'||par.attribute_start||':'||par.attribute_end)) AND NOT EXISTS(SELECT 1 FROM calls c WHERE c.__path=n.__path AND c.callee_id=n.id) AND NOT EXISTS(SELECT 1 FROM assignments a WHERE a.__path=n.__path AND (a.value=n.id OR a.target=n.id)) AND par.kind!='delete_statement'",('__path','id')),
      S('pseudo_fingerprints',"SELECT __path,id,'' dump_sha256 FROM pseudo_cached",('__path','id')),
    ]
    index=next(i for i,stage in enumerate(stages) if stage['name']=='actual_functions')
    stages[index:index]=pseudo
    stages[index+len(pseudo)]['query']+=" UNION ALL SELECT p.__path,p.id,p.function,h.dump_sha256,h.dump_sha256 FROM pseudo_cached p JOIN pseudo_fingerprints h ON h.__path=p.__path AND h.id=p.id"
    extra=next(stage for stage in stages if stage['name']=='extra_cached_errors')
    extra['query']+=" UNION ALL SELECT __path,id,error FROM pseudo_cached"
    return build(stages,output('diagnostics','policy_violations'),'cached-policy',{'annotation_values':('SELECT p.__path,p.annotation id FROM parameters p JOIN cache_arguments a ON a.__path=p.__path AND a.fn=p.fn AND a.name=p.name WHERE p.annotation IS NOT NULL',['unparse','repr_unparse']),'coordinates':('SELECT __path,id FROM coordinate_roots',['column']),'fingerprints':('SELECT __path,id FROM selected_functions',['body_sha256','signature_sha256']),'pseudo_fingerprints':('SELECT __path,id FROM pseudo_cached',['dump_sha256'])})


def runtime_contract(source):
    from data_layer_eight.contracts import constants
    from data_layer_generate_batch_seven import constant
    contracts=constants(source/'scripts/verify_cached_pure_lazy_allowlist.py')
    rows=[]
    for label,path,key in [('purity','l2055_lazy_result/purity.py','PURITY_RUNTIME_SYMBOLS'),('policy',ANCHOR,'POLICY_RUNTIME_SYMBOLS'),('optimizer_cache','l2070_batching/optimizer_run_cache.py','OPTIMIZER_CACHE_RUNTIME_SYMBOLS')]:
        rows.extend((label,path,name) for name in sorted(contracts[key]))
    catalog=' UNION ALL '.join('SELECT '+q(label)+' label,'+q(path)+' path,'+q(name)+' name' for label,path,name in rows)
    pub=constant(source/'l2070_batching/allowlist_signing.py','PUBLIC_KEY_HEX')
    stages=[*model(),
      S('protected_names',catalog,('path','name')),
      S('runtime_nodes',"SELECT p.label,p.name,n.__path,n.id FROM protected_names p JOIN nodes n ON n.__path=p.path LEFT JOIN nodes wrapper ON wrapper.__path=n.__path AND wrapper.id=n.parent AND wrapper.kind='decorated_definition' JOIN nodes parent ON parent.__path=n.__path AND parent.id=coalesce(wrapper.parent,n.parent) WHERE (n.kind IN ('function_definition','class_definition') AND n.name_source=p.name AND parent.kind='module') OR (n.kind='assignment' AND n.left_source=p.name AND parent.kind='expression_statement' AND EXISTS(SELECT 1 FROM nodes m WHERE m.__path=parent.__path AND m.id=parent.parent AND m.kind='module'))",('__path','id')),
      S('runtime_dumps',"SELECT __path,id,'' dump FROM runtime_nodes",('__path','id')),
      S('runtime_hash',"SELECT sha256(group_concat(value,'|')) actual FROM (SELECT r.label||':'||r.name||':'||d.dump value FROM runtime_nodes r JOIN runtime_dumps d ON d.__path=r.__path AND d.id=r.id ORDER BY r.name)"),
      S('entry_keywords',"SELECT k.__path,k.value id,k.name,c.id entry FROM calls c JOIN keywords k ON k.__path=c.__path AND k.call=c.id JOIN assignments a ON a.__path=c.__path AND c.__start>=a.right_start AND c.__end<=a.right_end WHERE c.__path="+q(ANCHOR)+" AND c.callee IN ('CachedPureLazyPolicyEntry','MemoizedPureLazyPolicyEntry') AND a.target_text IN ('_POLICY_ENTRIES','_MEMOIZED_POLICY_ENTRIES')",('__path','id')),
      S('metadata_assignments',"SELECT a.__path,a.value id,a.target_text name FROM assignments a WHERE a.__path="+q(ANCHOR)+" AND a.target_text IN ('ALLOWLIST_SIGNATURE','ALLOWLIST_NAME','ALLOWLIST_VERSION','CACHED_PURE_LAZY_RUNTIME_SOURCE_HASH','CACHED_PURE_LAZY_RUNTIME_SYMBOL_NAMES')",('__path','id')),
      S('literal_roots',"SELECT __path,id FROM entry_keywords UNION SELECT __path,id FROM metadata_assignments",('__path','id')),
      S('literal_values',"SELECT __path,id,'' literal_json FROM literal_roots",('__path','id')),
      S('metadata',"SELECT m.name,json_extract(v.literal_json,'$') value,v.literal_json FROM metadata_assignments m JOIN literal_values v ON v.__path=m.__path AND v.id=m.id",('name',)),
      S('canonical_entries',"SELECT entry,json_group_object(name,json(literal_json)) value FROM (SELECT k.entry,k.name,v.literal_json FROM entry_keywords k JOIN literal_values v ON v.__path=k.__path AND v.id=k.id ORDER BY k.entry,k.name) GROUP BY entry"),
      S('runtime_metadata',"SELECT json_object('runtime_source_hash',(SELECT value FROM metadata WHERE name='CACHED_PURE_LAZY_RUNTIME_SOURCE_HASH'),'runtime_symbols',json((SELECT literal_json FROM metadata WHERE name='CACHED_PURE_LAZY_RUNTIME_SYMBOL_NAMES'))) value"),
      S('signed_payload',"SELECT json_object('allowlist',json_group_array(value),'linter',(SELECT value FROM metadata WHERE name='ALLOWLIST_NAME'),'version',(SELECT value FROM metadata WHERE name='ALLOWLIST_VERSION')) message FROM (SELECT value FROM (SELECT value FROM canonical_entries UNION ALL SELECT value FROM runtime_metadata) ORDER BY value)"),
      S('signature_valid',"SELECT verify_ed25519("+q(pub)+",p.message,(SELECT value FROM metadata WHERE name='ALLOWLIST_SIGNATURE')) valid FROM signed_payload p"),
      S('diagnostics',"SELECT 'cached pure-lazy runtime symbol metadata changed' issue WHERE (SELECT count(*) FROM json_each((SELECT literal_json FROM metadata WHERE name='CACHED_PURE_LAZY_RUNTIME_SYMBOL_NAMES')))!=(SELECT count(*) FROM protected_names) OR EXISTS(SELECT name FROM protected_names EXCEPT SELECT value FROM json_each((SELECT literal_json FROM metadata WHERE name='CACHED_PURE_LAZY_RUNTIME_SYMBOL_NAMES'))) UNION ALL SELECT 'cached pure-lazy runtime source hash changed: actual='||h.actual||' policy='||m.value FROM runtime_hash h JOIN metadata m ON m.name='CACHED_PURE_LAZY_RUNTIME_SOURCE_HASH' WHERE h.actual!=m.value UNION ALL SELECT 'cached pure-lazy policy signature is invalid' FROM signature_valid WHERE NOT valid"),
    ]
    return build(stages,{'$option':'entryPoint','cases':{'all':"SELECT "+q(ANCHOR)+" path,0 start_byte,0 end_byte,issue,issue identity FROM diagnostics"},'default':"SELECT "+q(ANCHOR)+" path,0 start_byte,0 end_byte,issue,issue identity FROM diagnostics WHERE 0"},'cached-runtime-contract',{'runtime_dumps':('SELECT __path,id FROM runtime_nodes',['dump']),'literal_values':('SELECT __path,id FROM literal_roots',['literal_json'])})
